# owner: platform
"""Short absence notices to send home to parents."""

from datetime import date
from typing import Iterable, List

from rosterkit.attendance import days_missed
from rosterkit.models import Mark, Student

# ---
def format_day(day: date) -> str:
    """Spell a date the way a parent would read it."""
    return f"{day:%B} {day.day}, {day.year}"

# ---
def count_phrase(count: int) -> str:
    noun = "day" if count == 1 else "days"
    return f"{count} {noun}"

# ---
def check_student(
    student: Student, marks: List[Mark]
) -> None:
    ids = {mark.student_id for mark in marks}
    extra = ids - {student.student_id}
    if extra:
        raise ValueError(f"other students: {sorted(extra)}")

# ---
def absence_days(marks: List[Mark]) -> List[date]:
    days = days_missed(marks)
    if not days:
        raise ValueError("no absences to report")
    return days

# ---
def notice_text(student: Student, days: List[date]) -> str:
    name = f"{student.first_name} {student.last_name}"
    dates = "; ".join(format_day(day) for day in days)
    return (
        f"Dear parent or guardian, {name} missed "
        f"{count_phrase(len(days))} on {dates}."
    )

# ---
def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice for a parent listing the absent days."""
    entries = list(marks)
    check_student(student, entries)
    return notice_text(student, absence_days(entries))

