# owner: platform
import unittest
from datetime import date

from rosterkit.models import Mark, Student
from rosterkit.notices import (
    absence_notice,
    count_phrase,
    format_day
)

BRAM = Student("1001", "Thistle", "Bram", "A")

# ---
def mark(day, status, student_id="1001"):
    return Mark(student_id, date(2026, 9, day), status)

class FormatTests(unittest.TestCase):
    def test_spelled_out_date(self):
        day = format_day(date(2026, 9, 3))
        self.assertEqual(day, "September 3, 2026")

    def test_count_phrase_singular_and_plural(self):
        self.assertEqual(count_phrase(1), "1 day")
        self.assertEqual(count_phrase(2), "2 days")

class AbsenceNoticeTests(unittest.TestCase):
    def test_full_text(self):
        expected = (
            "Dear parent or guardian, Bram Thistle "
            "missed 1 day on September 5, 2026."
        )
        notice = absence_notice(BRAM, [mark(5, "absent")])
        self.assertEqual(notice, expected)

    def test_lists_absent_days_in_order(self):
        marks = [mark(5, "absent"), mark(3, "absent")]
        expected = (
            "2 days on September 3, 2026; "
            "September 5, 2026."
        )
        self.assertIn(expected, absence_notice(BRAM, marks))

    def test_excused_days_are_left_out(self):
        marks = [mark(1, "excused"), mark(2, "absent")]
        expected = "missed 1 day on September 2, 2026."
        self.assertIn(expected, absence_notice(BRAM, marks))

    def test_accepts_any_iterable_of_marks(self):
        marks = iter([mark(2, "absent")])
        notice = absence_notice(BRAM, marks)
        self.assertIn("missed 1 day", notice)

    def test_mark_for_another_student_is_rejected(self):
        other = mark(2, "absent", student_id="1002")
        marks = [mark(2, "absent"), other]
        with self.assertRaises(ValueError):
            absence_notice(BRAM, marks)

    def test_no_absences_is_rejected(self):
        marks = [mark(2, "present")]
        with self.assertRaises(ValueError):
            absence_notice(BRAM, marks)

    def test_no_marks_is_rejected(self):
        with self.assertRaises(ValueError):
            absence_notice(BRAM, [])
